TYPE_FALLBACK = {
    'aberration': 'tentacle-strike', 'beast': 'wolf-head', 'celestial': 'angel-wings', 'construct': 'golem-head', 'dragon': 'dragon-head',
    'elemental': 'fire-silhouette', 'fey': 'fairy', 'fiend': 'devil-mask', 'giant': 'giant', 'humanoid': 'cowled', 'monstrosity': 'hydra',
    'ooze': 'slime', 'plant': 'evil-tree', 'undead': 'skeleton',
}


def icon_for(m):
    i = m['index']
    if i in EXPLICIT:
        return EXPLICIT[i]
    if 'dragon' in i:
        if i.startswith('ancient'):
            return 'spiked-dragon-head'
        if 'wyrmling' in i:
            return 'dragon-breath'
        if i.startswith('young'):
            return 'dragon-head'
        return 'double-dragon' if False else 'dragon-head'
    t = m['type'].split(' ')[-1]
    return TYPE_FALLBACK.get(m['type'], TYPE_FALLBACK.get(t, 'cowled'))
